def _lvl(s):
    return s
def _list(d, extra=True):
    out = []
    for n, (ben, pw, ms) in d.items():
        t = "**Benefit.** " + ben
        for p in pw:
            t += "\n**Power.** " + p
        out.append([n, t])
    return out
def _mast(d):
    out = []
    for n, (ben, pw, ms) in d.items():
        if not ms: continue
        out.append([n, "\n".join("**Mastery Power.** " + m for m in ms)])
    return out

RUNE_LIST = _list(RUNES); RUNE_MAST = _mast(RUNES)
GLYPH_LIST = _list(GLYPHS); GLYPH_MAST = _mast(GLYPHS)

